def check_girth_fast(adj, n, max_cycle=5):
    """Check if girth >= 6 by looking for cycles of length 3, 4, 5"""
    # Check triangles
    for i in range(n):
        neighbors = list(adj[i])
        for j_idx in range(len(neighbors)):
            for k_idx in range(j_idx+1, len(neighbors)):
                j, k = neighbors[j_idx], neighbors[k_idx]
                if k in adj[j]:
                    return False

    # Check 4-cycles: for each pair of vertices, check if they have 2+ common neighbors
    for i in range(n):
        for j in range(i+1, n):
            common = len(adj[i] & adj[j])
            if common >= 2:
                return False

    # Check 5-cycles using BFS from each vertex
    for start in range(n):
        dist = {start: 0}
        parent = {start: -1}
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    cycle_len = dist[u] + dist[v] + 1
                    if cycle_len <= 5:
                        return False

    return True

def check_4colorable(adj, n):
    """Check 4-colorability using DSatur heuristic"""
    colors = [-1] * n
    degrees = [len(adj[i]) for i in range(n)]

    # Order vertices by degree (descending)
    order = sorted(range(n), key=lambda x: -degrees[x])

    def backtrack(idx):
        if idx == n:
            return True
        v = order[idx]
        used_colors = set()
        for neighbor in adj[v]:
            if colors[neighbor] >= 0:
                used_colors.add(colors[neighbor])
        for c in range(4):
            if c not in used_colors:
                colors[v] = c
                if backtrack(idx + 1):
                    return True
                colors[v] = -1
        return False

    return backtrack(0)

def build_adj(edges, n):
    adj = [set() for _ in range(n)]
    for u, v in edges:
